from datetime import datetime, timedelta
import csv

# Read the CSV file
readings = []
with open('/app/readings.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        readings.append({
            'meter_id': row['meter_id'],
            'ts': row['ts'],
            'register_kwh': float(row['register_kwh'])
        })

# Helper function to convert UTC to site local time
def utc_to_local(utc_str):
    dt_utc = datetime.fromisoformat(utc_str)
    dst_end = datetime(2026, 11, 1, 9, 0, 0)  # 2:00 AM PST = 9:00 AM UTC
    if dt_utc < dst_end:
        offset = timedelta(hours=-7)
    else:
        offset = timedelta(hours=-8)
    return dt_utc + offset

# The key insight: After Nov 13 10:00, multiply by 10
# This means the readings after 10:00 are already in 1/10 scale

# Let me look at the raw consumption pattern
# Hourly consumption is the delta between consecutive readings

# For M-1001, Nov in detail
m1001_nov = []
for r in readings:
    if r['meter_id'] == 'M-1001':
        local_dt = utc_to_local(r['ts'])
        if local_dt.year == 2026 and local_dt.month == 11:
            m1001_nov.append({
                'local_ts': local_dt,
                'register_kwh': r['register_kwh']
            })

m1001_nov = sorted(m1001_nov, key=lambda x: x['local_ts'])

# Calculate hourly consumption
print("Hourly consumption patterns:")
print("\nBefore CT change (sample):")
for i in range(1, min(6, len(m1001_nov))):
    prev = m1001_nov[i-1]
    curr = m1001_nov[i]
    delta = curr['register_kwh'] - prev['register_kwh']
    if delta < 0:
        # Rollover
        delta = 1000000 + delta
    print(f"  {curr['local_ts']}: delta = {delta:.1f}")

# Around the rollover
rollover_idx = None
for i in range(len(m1001_nov) - 1):
    if m1001_nov[i+1]['register_kwh'] < m1001_nov[i]['register_kwh'] * 0.5:
        rollover_idx = i
        break

if rollover_idx:
    print(f"\nAround rollover (index {rollover_idx}):")
    for i in range(max(0, rollover_idx - 2), min(len(m1001_nov), rollover_idx + 5)):
        if i == 0:
            print(f"  {m1001_nov[i]['local_ts']}: register = {m1001_nov[i]['register_kwh']:.1f}")
        else:
            delta = m1001_nov[i]['register_kwh'] - m1001_nov[i-1]['register_kwh']
            if delta < 0:
                delta = 1000000 + delta
            print(f"  {m1001_nov[i]['local_ts']}: register = {m1001_nov[i]['register_kwh']:.1f}, hourly = {delta:.1f}")

# Around CT change
